// Package apiconv converts ent entities into the ogen-generated API DTOs.
//
// The per-field struct mapping is generated by goverter (apiconv.gen.go). Only
// the irreducible bridges for ogen's Nil* wrapper types (which are custom value
// types goverter cannot infer) are declared here as extends — written once and
// reused by every generated mapping.
package apiconv

import (
	"time"

	"github.com/lib/pq"
	"github.com/samber/lo"

	"hexletbasics/ent"
	"hexletbasics/internal/api"
	"hexletbasics/internal/progress"
)

//go:generate go tool goverter gen hexletbasics/internal/apiconv

// Converter maps ent rows to the generated API DTOs.
//
// goverter:converter
// goverter:output:file ./apiconv.gen.go
// goverter:useZeroValueOnPointerInconsistency yes
// goverter:extend Int32FromInt
// goverter:extend Int32FromPtr
// goverter:extend StringFromPtr
// goverter:extend NilStringFromPtr
// goverter:extend NilInt32FromPtr
// goverter:extend NilBoolFromPtr
// goverter:extend NilDateTimeFromPtr
// goverter:extend NilLearnAsFromPtr
// goverter:extend NilReadinessFromPtr
// goverter:extend NilReviewStateFromPtr
// goverter:extend NilReviewLocaleFromPtr
// goverter:extend NilLandingPageStateFromPtr
// goverter:extend PermissionResourceFromString
// goverter:extend LocalesFromPq
// goverter:extend NilCourseVersionFromEnt
// goverter:extend TimeIdentity
// goverter:extend EnrollmentStateFromPtr
type Converter interface {
	ToCatalogItems(source []*ent.LandingPage) []api.CourseCatalogItem

	// goverter:map Edges.Course Course
	// goverter:map Edges.Course.MembersCount EnrollmentsCount
	// goverter:map . CoverUrl | coverURLNull
	// goverter:ignore Duration
	ToCatalogItem(source *ent.LandingPage) api.CourseCatalogItem

	// Every api.Course field maps from real ent data, mirroring LanguageResource:
	// direct columns (createdAt, currentVersionId, hexletProgramLandingPage), the
	// current_version association, and the serializer's computed fields as bridges
	// below. Only the ActiveStorage cover variants stay deferred (same reason as
	// CourseCatalogItem.CoverUrl — blob assets are not migrated yet).
	// The two legacy column names the contract renamed: `progress` carries
	// Course Readiness, `members_count` counts Enrollments.
	// goverter:map Progress Readiness
	// goverter:map MembersCount EnrollmentsCount
	// goverter:map CategoryID CategoryId
	// goverter:map CurrentVersionID CurrentVersionId
	// goverter:map Edges.CurrentVersion CurrentVersion
	// goverter:map . RepositoryUrl | repositoryURL
	// goverter:map . HexletProgramLandingPage | hexletProgramLandingPage
	// goverter:map . RatingCount | ratingCount
	// goverter:map . RatingValue | ratingValue
	// goverter:map . CoverListVariant | coverVariantNull
	// goverter:map . CoverThumbVariant | coverVariantNull
	ToCourse(source *ent.Course) api.Course

	ToCourses(source []*ent.Course) []api.Course

	ToCourseCategory(source *ent.CourseCategory) api.CourseCategory

	ToCourseCategories(source []*ent.CourseCategory) []api.CourseCategory

	ToBanner(source *ent.Banner) api.Banner

	ToBanners(source []*ent.Banner) []api.Banner

	// Lead.FullName is derived from the associated user in the legacy serializer;
	// until the User schema lands it stays null (contract allows it). UserID
	// carries the DB casing, so it is mapped explicitly to the api's UserId.
	// goverter:map UserID UserId
	// goverter:map . FullName | leadFullNameNull
	ToLead(source *ent.Lead) api.Lead

	ToLeads(source []*ent.Lead) []api.Lead

	// UserCrud is the admin list/form projection of a user: id + the four
	// directly-editable columns. All fields map by name from the ent row.
	ToUserCrud(source *ent.User) api.UserCrud

	ToUserCruds(source []*ent.User) []api.UserCrud

	// User is the rich serializer projection (mirrors UserResource): the direct
	// columns plus the computed name, can_access_admin, created_at timestamp and
	// the constant "user" type discriminator.
	// goverter:map . Name | userName
	// goverter:map . CanAccessAdmin | userCanAccessAdmin
	// goverter:map . CreatedAtAsTimestamp | userCreatedAtAsTimestamp
	// goverter:map . Type | userType
	ToUser(source *ent.User) api.User

	// Review embeds the full course and user (loaded via WithCourse/WithUser).
	// courseId is the legacy `language_id` column; full_name joins the review's
	// own first/last name (mirrors ReviewResource#full_name).
	// goverter:map Edges.Course Course
	// goverter:map Edges.User User
	// goverter:map CourseID CourseId
	// goverter:map UserID UserId
	// goverter:map . FullName | reviewFullName
	ToReview(source *ent.Review) api.Review

	ToReviews(source []*ent.Review) []api.Review

	// QnA items (category + landing page) share the flat {id, question, answer}
	// projection; the nullable ent columns resolve to required strings.
	ToCategoryQnaItem(source *ent.CategoryQnaItem) api.QnaItem

	ToCategoryQnaItems(source []*ent.CategoryQnaItem) []api.QnaItem

	ToLandingPageQnaItem(source *ent.LandingPageQnaItem) api.QnaItem

	ToLandingPageQnaItems(source []*ent.LandingPageQnaItem) []api.QnaItem

	// CourseLandingPage is the admin projection of a landing page. courseSlug,
	// duration and membersCount come from the associated course (loaded via
	// WithCourse); outcomesImage stays null until blob assets are migrated (same
	// deferral as the course cover). Required-string fields resolve from nullable
	// columns via StringFromPtr.
	// goverter:map CourseID CourseId
	// goverter:map LandingPageToRedirectID LandingPageToRedirectId
	// goverter:map Edges.Course.Slug CourseSlug
	// goverter:map Edges.Course.MembersCount EnrollmentsCount
	// goverter:map Edges.Course Duration | courseDuration
	// goverter:map . OutcomesImage | landingOutcomesImageNull
	ToCourseLandingPage(source *ent.LandingPage) api.CourseLandingPage

	ToCourseLandingPages(source []*ent.LandingPage) []api.CourseLandingPage

	// StaffRole is the list projection: permissionsCount is the size of the
	// loaded permissions edge.
	// goverter:map . PermissionsCount | staffRolePermissionsCount
	ToStaffRole(source *ent.StaffRole) api.StaffRole

	ToStaffRoles(source []*ent.StaffRole) []api.StaffRole

	// StaffRoleDetail carries the full permission matrix (loaded via
	// WithPermissions).
	// goverter:map Edges.Permissions Permissions
	ToStaffRoleDetail(source *ent.StaffRole) api.StaffRoleDetail

	// goverter:map RoleID RoleId
	ToStaffRolePermission(source *ent.StaffRolePermission) api.StaffRolePermission

	// StaffMember embeds the full user and role (loaded via WithUser/WithRole);
	// allowedLocales is the native pg array bridged by LocalesFromPq.
	// goverter:map UserID UserId
	// goverter:map RoleID RoleId
	// goverter:map Edges.User User
	// goverter:map Edges.Role Role
	ToStaffMember(source *ent.StaffMember) api.StaffMember

	ToStaffMembers(source []*ent.StaffMember) []api.StaffMember

	// Lesson list rows are version infos with the stable lesson identity loaded
	// through WithLesson.
	// goverter:map CourseLessonID ID
	// goverter:map Edges.Lesson.Slug Slug
	ToCourseLessonListItem(source *ent.CourseLessonTranslation) api.CourseLessonListItem

	ToCourseLessonListItems(source []*ent.CourseLessonTranslation) []api.CourseLessonListItem

	// Lesson progress projections require WithCourse and WithLesson; the lesson
	// query additionally eager-loads locale-filtered infos in ascending id order.
	// goverter:map UserID UserId
	// goverter:map Edges.Course.Slug CourseSlug
	// goverter:map Edges.Lesson.Slug CourseLessonSlug
	// goverter:map . CourseLessonName | lessonProgressLessonName
	ToLessonProgress(source *ent.LessonProgress) api.LessonProgress

	ToLessonProgressList(source []*ent.LessonProgress) []api.LessonProgress

	// Assistant messages are the admin read model over `ai_messages` (legacy
	// AiMessageResource). Course/lesson identity travels through
	// chat → lesson progress → course/lesson; the handler eager-loads the
	// lesson's locale-filtered infos so the name resolves like the lesson
	// progress list.
	// goverter:map UserID UserId
	// goverter:map Edges.Chat.Edges.LessonProgress.Edges.Course.Slug CourseSlug
	// goverter:map Edges.Chat.Edges.LessonProgress.Edges.Lesson.Slug CourseLessonSlug
	// goverter:map . CourseLessonName | assistantMessageLessonName
	ToLessonAssistantMessage(source *ent.AiMessage) api.LessonAssistantMessage

	ToLessonAssistantMessages(source []*ent.AiMessage) []api.LessonAssistantMessage

	// Review projections require WithCourse and WithLesson.
	// goverter:map CourseID CourseId
	// goverter:map CourseLessonID CourseLessonId
	// goverter:map CourseLessonVersionID CourseLessonVersionId
	// goverter:map CourseLessonTranslationID CourseLessonVersionInfoId
	// goverter:map Edges.Lesson.Slug Slug
	// goverter:map Edges.Lesson.NaturalOrder LessonNaturalOrder
	// goverter:map Edges.Course.Slug CourseSlug
	ToCourseLessonReview(source *ent.CourseLessonReview) api.CourseLessonReview

	ToCourseLessonReviews(source []*ent.CourseLessonReview) []api.CourseLessonReview
}

// ToEnrollment projects a learner's Enrollment together with the computed
// progress that belongs to it. goverter maps ent rows field by field; this one
// is hand-written because the payload is half row, half computation — the
// percentage and the availability flags exist nowhere in storage.
func ToEnrollment(row *ent.Enrollment, state *progress.CourseState) api.Enrollment {
	return api.Enrollment{
		ID:             int32(row.ID),
		UserId:         int32(row.UserID),
		CourseId:       int32(row.CourseID),
		State:          nilEnrollmentState(row.State),
		Completion:     int32(state.Completion),
		NextLessonName: NilStringFromPtr(state.NextLessonSlug),
		Progress:       ToCourseProgress(state),
	}
}

// ToCourseProgress projects the computed course state. Availability travels
// with it so the client renders locks from the server's answer instead of
// reimplementing the gate.
func ToCourseProgress(state *progress.CourseState) api.CourseProgress {
	lessons := make([]api.LessonProgressItem, 0, len(state.Lessons))
	for _, lesson := range state.Lessons {
		lessons = append(lessons, api.LessonProgressItem{
			Slug:      lesson.Slug,
			Position:  int32(lesson.Position),
			Finished:  lesson.Finished,
			Available: lesson.Available,
		})
	}
	return api.CourseProgress{
		State:                    nilEnrollmentState(&state.State),
		Completion:               int32(state.Completion),
		NextLessonSlug:           NilStringFromPtr(state.NextLessonSlug),
		FurthestFinishedPosition: int32(state.FurthestFinishedPosition),
		Lessons:                  lessons,
	}
}

// nilEnrollmentState resolves the nullable legacy column to the contract's
// nilable enum: a learner with no Enrollment has no state at all, which is the
// "not started" condition rather than a state a record can be in.
func nilEnrollmentState(v *string) api.NilEnrollmentState {
	if v == nil || *v == "" {
		return api.NilEnrollmentState{Null: true}
	}
	return api.NewNilEnrollmentState(api.EnrollmentState(*v))
}

// TimeIdentity copies a time.Time as-is, so goverter treats it as a scalar
// instead of deep-copying its unexported fields.
func TimeIdentity(v time.Time) time.Time { return v }

// Int32FromInt narrows an ent int id/count to the contract's int32.
func Int32FromInt(v int) int32 { return int32(v) }

// Int32FromPtr resolves a nullable ent integer to a required contract field.
func Int32FromPtr(v *int) int32 { return int32(lo.FromPtr(v)) }

// StringFromPtr resolves a nullable ent column to a required string field.
func StringFromPtr(v *string) string { return lo.FromPtr(v) }

// EnrollmentStateFromPtr mirrors AASM's initial state for nullable legacy rows.
func EnrollmentStateFromPtr(v *string) api.EnrollmentState {
	if v == nil || *v == "" {
		return api.EnrollmentStateStarted
	}
	return api.EnrollmentState(*v)
}

// lessonProgressLessonName reads the first eager-loaded localized info. The
// handler orders the edge by id so "first" is deterministic and matches the
// legacy Lesson#localed_info convention.
func lessonProgressLessonName(source *ent.LessonProgress) string {
	if source == nil || source.Edges.Lesson == nil || len(source.Edges.Lesson.Edges.Infos) == 0 {
		return ""
	}
	return StringFromPtr(source.Edges.Lesson.Edges.Infos[0].Name)
}

// assistantMessageLessonName resolves the lesson display name through
// chat → lesson progress → lesson → first eager-loaded localized info (the same
// convention as lessonProgressLessonName, which it reuses).
func assistantMessageLessonName(source *ent.AiMessage) string {
	if source == nil || source.Edges.Chat == nil || source.Edges.Chat.Edges.LessonProgress == nil {
		return ""
	}
	return lessonProgressLessonName(source.Edges.Chat.Edges.LessonProgress)
}

// NilStringFromPtr bridges a nullable ent column to ogen's NilString.
func NilStringFromPtr(v *string) api.NilString {
	if v == nil {
		return api.NilString{Null: true}
	}
	return api.NewNilString(*v)
}

// NilInt32FromPtr bridges a nullable ent int to ogen's NilInt32.
func NilInt32FromPtr(v *int) api.NilInt32 {
	if v == nil {
		return api.NilInt32{Null: true}
	}
	return api.NewNilInt32(int32(*v))
}

// NilBoolFromPtr bridges a nullable ent bool column to ogen's NilBool.
func NilBoolFromPtr(v *bool) api.NilBool {
	if v == nil {
		return api.NilBool{Null: true}
	}
	return api.NewNilBool(*v)
}

// NilDateTimeFromPtr bridges a nullable ent time column to ogen's NilDateTime.
func NilDateTimeFromPtr(v *time.Time) api.NilDateTime {
	if v == nil {
		return api.NilDateTime{Null: true}
	}
	return api.NewNilDateTime(*v)
}

// NilLearnAsFromPtr bridges a nullable ent string to ogen's NilCourseLearnAs.
func NilLearnAsFromPtr(v *string) api.NilCourseLearnAs {
	if v == nil {
		return api.NilCourseLearnAs{Null: true}
	}
	return api.NewNilCourseLearnAs(api.CourseLearnAs(*v))
}

// NilReadinessFromPtr bridges a nullable ent string to ogen's NilCourseReadiness.
func NilReadinessFromPtr(v *string) api.NilCourseReadiness {
	if v == nil {
		return api.NilCourseReadiness{Null: true}
	}
	return api.NewNilCourseReadiness(api.CourseReadiness(*v))
}

// coverURLNull keeps CoverUrl null until course cover assets are re-uploaded.
func coverURLNull(*ent.LandingPage) api.NilString {
	return api.NilString{Null: true}
}

// leadFullNameNull keeps Lead.FullName null until the User schema lands and the
// name can be derived from the associated user (legacy serializer behavior).
func leadFullNameNull(*ent.Lead) api.NilString {
	return api.NilString{Null: true}
}

// NilReviewStateFromPtr bridges a nullable ent string to ogen's NilReviewState.
func NilReviewStateFromPtr(v *string) api.NilReviewState {
	if v == nil {
		return api.NilReviewState{Null: true}
	}
	return api.NewNilReviewState(api.ReviewState(*v))
}

// NilReviewLocaleFromPtr bridges a nullable ent string to ogen's NilReviewLocale.
func NilReviewLocaleFromPtr(v *string) api.NilReviewLocale {
	if v == nil {
		return api.NilReviewLocale{Null: true}
	}
	return api.NewNilReviewLocale(api.ReviewLocale(*v))
}

// joinName joins a first/last name pair with a single space, treating a nil
// component as empty — mirrors the Ruby `[first, last].join(" ")` serializers.
func joinName(first, last *string) string {
	return lo.FromPtr(first) + " " + lo.FromPtr(last)
}

// userName mirrors UserResource#name.
func userName(u *ent.User) api.NilString {
	return api.NewNilString(joinName(u.FirstName, u.LastName))
}

// userCanAccessAdmin mirrors UserResource#can_access_admin. Staff membership is
// not modeled yet, so this reflects the admin flag only; it will gain the staff
// check once the management schema lands (parity TODO, like ratingCount).
func userCanAccessAdmin(u *ent.User) bool {
	return lo.FromPtr(u.Admin)
}

// userCreatedAtAsTimestamp mirrors UserResource#created_at_as_timestamp (a Unix
// epoch used by the GTM/Wootric integration); always present.
func userCreatedAtAsTimestamp(u *ent.User) api.NilInt64 {
	return api.NewNilInt64(u.CreatedAt.Unix())
}

// userType is the constant "user" discriminator from UserResource.
func userType(*ent.User) api.UserType {
	return api.UserTypeUser
}

// reviewFullName mirrors ReviewResource#full_name: the review's own first/last
// name (the reviewer's display name, not the associated user's).
func reviewFullName(r *ent.Review) api.NilString {
	return api.NewNilString(joinName(r.FirstName, r.LastName))
}

// NilLandingPageStateFromPtr bridges a nullable ent string to ogen's
// NilLandingPageState.
func NilLandingPageStateFromPtr(v *string) api.NilLandingPageState {
	if v == nil {
		return api.NilLandingPageState{Null: true}
	}
	return api.NewNilLandingPageState(api.LandingPageState(*v))
}

// courseDuration mirrors Language#duration: estimated hours from the lesson
// count (lessons_count * 15 minutes, integer-divided to hours). Guards nil
// because a listed landing page may reference a course absent from the current
// query (or fixture) set — then duration reads as 0, matching `|| 0` upstream.
func courseDuration(c *ent.Course) int32 {
	if c == nil {
		return 0
	}
	return int32(c.LessonsCount * 15 / 60)
}

// PermissionResourceFromString bridges the ent resource column (a plain string)
// to the api's PermissionResource enum.
func PermissionResourceFromString(v string) api.PermissionResource {
	return api.PermissionResource(v)
}

// LocalesFromPq bridges the native pg text-array column to the api's plain
// []string (pq.StringArray is a []string, but goverter needs the named-type
// conversion spelled out).
func LocalesFromPq(v pq.StringArray) []string {
	return []string(v)
}

// staffRolePermissionsCount is the size of the role's loaded permissions edge,
// mirroring StaffRoleResource#permissions_count.
func staffRolePermissionsCount(r *ent.StaffRole) int32 {
	return int32(len(r.Edges.Permissions))
}

// landingOutcomesImageNull keeps OutcomesImage null until the landing-page
// outcomes image is migrated to blob storage (same deferral as the course
// cover — see coverURLNull).
func landingOutcomesImageNull(*ent.LandingPage) api.NilString {
	return api.NilString{Null: true}
}

// NilCourseVersionFromEnt bridges the current_version association to ogen's
// NilCourseVersion. The four exposed fields are mapped inline: constructing the
// Nil wrapper is the irreducible part goverter cannot infer, so hand-mapping the
// small CourseVersion body alongside it keeps the whole bridge in one place.
func NilCourseVersionFromEnt(v *ent.CourseVersion) api.NilCourseVersion {
	if v == nil {
		return api.NilCourseVersion{Null: true}
	}
	return api.NewNilCourseVersion(CourseVersionFromEnt(v))
}

// CourseVersionFromEnt maps an ent course version to the API body. Used both by
// the current-version bridge above and by the createVersion handler (which
// returns a bare CourseVersion for the 201).
func CourseVersionFromEnt(v *ent.CourseVersion) api.CourseVersion {
	return api.CourseVersion{
		ID:        int32(v.ID),
		Result:    NilStringFromPtr(v.Result),
		State:     NilStringFromPtr(v.State),
		CreatedAt: v.CreatedAt,
	}
}

// repositoryURL derives the exercises repo URL from the course slug, mirroring
// Language#repository_url. It is always present (the legacy method never returns
// nil), so the nullable API field carries a value.
func repositoryURL(c *ent.Course) api.NilString {
	return api.NewNilString("https://github.com/hexlet-basics/exercises-" + lo.FromPtr(c.Slug))
}

// hexletProgramLandingPage applies the legacy `.presence` semantics: a blank
// column reads as null rather than an empty string.
func hexletProgramLandingPage(c *ent.Course) api.NilString {
	if c.HexletProgramLandingPage == nil || *c.HexletProgramLandingPage == "" {
		return api.NilString{Null: true}
	}
	return api.NewNilString(*c.HexletProgramLandingPage)
}

// ratingCount reproduces the legacy serializer's placeholder rating count. The
// real aggregate over reviews is not implemented yet (the legacy code carries
// the same TODO); this keeps parity until it is.
func ratingCount(*ent.Course) int32 { return 89 }

// ratingValue reproduces the legacy serializer's placeholder rating: a fixed
// value keyed off id parity, pending a real reviews aggregate.
func ratingValue(c *ent.Course) float64 {
	if c.ID%2 == 0 {
		return 4
	}
	return 5
}

// coverVariantNull keeps the cover variant URLs null until course cover assets
// are migrated to blob storage (same deferral as coverURLNull).
func coverVariantNull(*ent.Course) api.NilString {
	return api.NilString{Null: true}
}
